{
    "swagger": "2.0",
    "info": {
        "version": "v1",
        "title": "Notebook data types"
    },
    "paths": {},
    "definitions": {
        "Notebooks": {
            "description": "A list of notebooks.",
            "required": [
                "value"
            ],
            "type": "object",
            "properties": {
                "value": {
                    "description": "A list of notebooks.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/Notebook"
                    }
                }
            },
            "allOf": [
                {
                    "$ref": "../common/definitions.json#/definitions/PaginatedResponse"
                }
            ]
        },
        "Notebook": {
            "description": "A notebook object.",
            "type": "object",
            "required": [
                "type"
            ],
            "allOf": [
                {
                    "$ref": "../common/definitions.json#/definitions/Item"
                }
            ]
        },
        "CreateNotebookRequest": {
            "description": "Create notebook request payload.",
            "required": [
                "displayName"
            ],
            "properties": {
                "displayName": {
                    "description": "The notebook display name. The display name must follow naming rules according to item type.",
                    "type": "string",
                    "readOnly": false
                },
                "description": {
                    "description": "The notebook description. Maximum length is 256 characters.",
                    "type": "string",
                    "readOnly": false
                },
                "folderId": {
                    "description": "The folder ID. If not specified or null, the notebook is created with the workspace as its folder.",
                    "type": "string",
                    "format": "uuid",
                    "readOnly": false
                },
                "definition": {
                    "description": "The notebook public definition.",
                    "$ref": "#/definitions/NotebookDefinition",
                    "readOnly": false
                },
                "sensitivityLabelSettings": {
                    "description": "The sensitivity label settings for the notebook.",
                    "$ref": "../common/definitions.json#/definitions/SensitivityLabelSettings",
                    "readOnly": false
                }
            }
        },
        "UpdateNotebookDefinitionRequest": {
            "description": "Update notebook public definition request payload.",
            "required": [
                "definition"
            ],
            "properties": {
                "definition": {
                    "$ref": "#/definitions/NotebookDefinition"
                }
            }
        },
        "NotebookDefinitionResponse": {
            "description": "Notebook public definition response.",
            "required": [
                "definition"
            ],
            "properties": {
                "definition": {
                    "$ref": "#/definitions/NotebookDefinition",
                    "readOnly": true
                }
            }
        },
        "NotebookDefinition": {
            "description": "Notebook public definition object. Refer to this [article](/rest/api/fabric/articles/item-management/definitions/notebook-definition) for more details on the structure of the Notebook definition.",
            "type": "object",
            "required": [
                "parts"
            ],
            "properties": {
                "format": {
                    "description": "The format of the Notebook definition. Supported format: `ipynb` and `fabricGitSource`. If no format is provided, `fabricGitSource` is used.",
                    "type": "string",
                    "readOnly": false
                },
                "parts": {
                    "description": "A list of definition parts.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/NotebookDefinitionPart"
                    },
                    "readOnly": false
                }
            }
        },
        "NotebookDefinitionPart": {
            "description": "Notebook definition part object.",
            "type": "object",
            "properties": {
                "path": {
                    "description": "The notebook part path. Supported notebook content extensions: `.ipynb` for `ipynb` format; `.py`, `.scala`, `.r`, `.sql` for `fabricGitSource` format.",
                    "type": "string",
                    "readOnly": false
                },
                "payload": {
                    "description": "The notebook part payload.",
                    "type": "string",
                    "readOnly": false
                },
                "payloadType": {
                    "description": "The payload type.",
                    "$ref": "../common/definitions.json#/definitions/PayloadType",
                    "readOnly": false
                }
            }
        },
        "UpdateNotebookRequest": {
            "description": "Update notebook request.",
            "properties": {
                "displayName": {
                    "description": "The notebook display name. The display name must follow naming rules according to item type.",
                    "type": "string",
                    "readOnly": false
                },
                "description": {
                    "description": "The notebook description. Maximum length is 256 characters.",
                    "type": "string",
                    "readOnly": false
                }
            }
        },
        "RunNotebookRequest": {
            "description": "Run notebook request with executionData.",
            "type": "object",
            "properties": {
                "executionData": {
                    "description": "Optional. The notebook configurations used during execution.",
                    "$ref": "#/definitions/RunNotebookExecutionData"
                },
                "parameters": {
                    "description": "The parameter list for run on-demand job request. Per-run, user-defined inputs to tailor this invocation. Note: parameter names are case-insensitive, but the casing must match the parameter name used in the code cell.",
                    "type": "array",
                    "items": {
                        "$ref": "../common/job_scheduling.json#/definitions/Parameter"
                    }
                }
            }
        },
        "ComputeType": {
            "type": "string",
            "description": "Represents the type of the compute. Additional `ComputeType` types may be added over time.",
            "enum": [
                "Spark",
                "Jupyter",
                "DataWarehouse"
            ],
            "x-ms-enum": {
                "name": "ComputeType",
                "modelAsString": true,
                "values": [
                    {
                        "value": "Spark",
                        "description": "Spark compute type."
                    },
                    {
                        "value": "Jupyter",
                        "description": "Jupyter compute type."
                    },
                    {
                        "value": "DataWarehouse",
                        "description": "Data Warehouse compute type."
                    }
                ]
            }
        },
        "RunNotebookExecutionData": {
            "description": "Execution data for the notebook run.",
            "type": "object",
            "required": [
                "compute"
            ],
            "properties": {
                "compute": {
                    "description": "The execution engine for the job instance. This value needs to match the language of the notebook.",
                    "$ref": "#/definitions/ComputeType"
                }
            },
            "discriminator": "compute"
        },
        "RunSparkNotebookExecutionData": {
            "type": "object",
            "description": "Spark notebook execution data.",
            "properties": {
                "computeConfiguration": {
                    "description": "The Spark notebook execution configuration.",
                    "$ref": "#/definitions/SparkNotebookComputeConfiguration"
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/RunNotebookExecutionData"
                }
            ],
            "x-ms-discriminator-value": "Spark"
        },
        "SparkNotebookComputeConfiguration": {
            "type": "object",
            "description": "Spark notebook compute configuration.",
            "properties": {
                "name": {
                    "description": "The name of this session.",
                    "type": "string"
                },
                "driverCores": {
                    "description": "Spark driver core. Must be one of the following values: 4, 8, 16, 32, 64.",
                    "format": "int32",
                    "type": "integer"
                },
                "driverMemory": {
                    "description": "Spark driver memory.",
                    "type": "string",
                    "$ref": "#/definitions/CustomPoolMemory"
                },
                "executorCores": {
                    "description": "Spark executor core. Must be one of the following values: 4, 8, 16, 32, 64.",
                    "format": "int32",
                    "type": "integer"
                },
                "executorMemory": {
                    "description": "Spark executor memory.",
                    "type": "string",
                    "$ref": "#/definitions/CustomPoolMemory"
                },
                "numExecutors": {
                    "description": "Number of executors to launch for this session. The minimum value is 1, and the maximum value has to be lower than the instance pool `maxNodeCount`.",
                    "format": "int32",
                    "type": "integer"
                },
                "jars": {
                    "description": "The list of abfs path of jars to be used in this session. Jars to include on the driver and executor classpaths.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "pyFiles": {
                    "description": "The list of abfs path of python files to be used in this session. `.zip`, `.egg`, or `.py` files to place on the PYTHONPATH for Python apps.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "files": {
                    "description": "The list of abfs path of files to be used in this session. Files to be placed in the working directory of each executor.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "archives": {
                    "description": "The list of abfs path of archives to be used in this session. Archives to be extracted into the working directory of each executor. `.jar`, `.tar.gz`, `.tgz` and `.zip` are supported. You can specify the directory name to unpack via adding # after the file name to unpack, for example, `file.zip#directory`.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "sparkProperties": {
                    "type": "array",
                    "description": "A dictionary of Spark property key to their value.",
                    "items": {
                        "$ref": "#/definitions/SparkProperty"
                    }
                },
                "instancePool": {
                    "description": "Instance pool used to run this notebook.",
                    "$ref": "../common/spark_definitions.json#/definitions/InstancePool"
                },
                "mountPoints": {
                    "description": "Mount points to be used in this session.",
