                },
                "attachedEnvironment": {
                    "description": "Environment to be used in this session.",
                    "$ref": "../common/definitions.json#/definitions/ItemReferenceById"
                },
                "highConcurrencyModeOptions": {
                    "description": "High concurrency mode options.",
                    "$ref": "#/definitions/HighConcurrencyModeOptions"
                }
            }
        },
        "CustomPoolMemory": {
            "type": "string",
            "description": "Custom pool memory for Spark driver or Spark executor. Additional `CustomPoolMemory` types may be added over time.",
            "enum": ["28g", "56g", "112g", "224g", "400g"],
            "x-ms-enum": {
                "name": "CustomPoolMemory",
                "modelAsString": true,
